import math

def is_power_of_two(n):
    return n > 0 and (n & (n - 1) == 0)

# We are testing n=3. The equation is x^3 + x = 2^k + 2, or x^3 + x - 2 = 2^k.
# We require x > 3 and x = 2 (mod 3).
# Test sequence: 5, 8, 11, 14, 17, 20, 23, ...

# Start with x = 5, as it is the known solution
x_start = 5
limit = 50 # Set a search limit for demonstration purposes

solutions = []
x = x_start
while x <= limit:
    # Check if x satisfies the condition x = 2 (mod 3)
    if x % 3 == 2:
        try:
            LHS = x**3 + x - 2
            if is_power_of_two(LHS):
                # Calculate k
                k = int(math.log2(LHS))
                solutions.append((x, 3, k))
        except OverflowError:
            # Stop if numbers get too large for standard integer types, though python handles large ints
            print(f"Stopped search at x={x} due to potential overflow in calculation.")
            break
    x += 3

print("Found solutions (x, 3, k) for x <= 50:")
if solutions:
    for sol in solutions:
        print(f"({sol[0]}, {sol[1]}, {sol[2]})")
else:
    print("No solutions found in the range.")

def is_power_of_two(n):
    if n <= 0:
        return False
    return (n & (n - 1) == 0)

def check_case(n, x):
    if x <= n or x % 3 != 2:
        return None, "Constraints not met"

    # We need to check if x^n + x - 2 is a power of 2
    try:
        lhs_minus_2 = x**n + x - 2
    except OverflowError:
        return None, "Calculation overflowed for these inputs"

    if lhs_minus_2 <= 0:
        return None, "LHS - 2 is non-positive"

    if is_power_of_two(lhs_minus_2):
        # k = log2(lhs_minus_2)
        k = lhs_minus_2.bit_length() - 1

        # Constraint 2 also requires k to be even
        if k % 2 == 0:
            return (x, n, k), None
        else:
            return (x, n, k), "k is odd"
    else:
        return None, "Not a power of 2"

# --- Investigation for n=4 ---
